class Solution:
 def removeOuterParentheses(self,s):
  depth=0;out=[]
  for c in s:
   if c=='(':
    if depth:out.append(c)
    depth+=1
   else:
    depth-=1
    if depth:out.append(c)
  return ''.join(out)

class Solution:
 def sumRootToLeaf(self,root):
  def dfs(n,value):
   if n is None:return 0
   value=value*2+n.val
   if n.left is None and n.right is None:return value
   return dfs(n.left,value)+dfs(n.right,value)
  return dfs(root,0)

class Solution:
 def allCellsDistOrder(self,rows,cols,rCenter,cCenter):
  return sorted(([r,c] for r in range(rows) for c in range(cols)),key=lambda p:(abs(p[0]-rCenter)+abs(p[1]-cCenter),p[0],p[1]))

class Solution:
 def isBoomerang(self,points):
  (x1,y1),(x2,y2),(x3,y3)=points
  return (x2-x1)*(y3-y1)!=(y2-y1)*(x3-x1)

import heapq
class Solution:
 def lastStoneWeight(self,stones):
  h=[-x for x in stones];heapq.heapify(h)
  while len(h)>1:
   a=-heapq.heappop(h);b=-heapq.heappop(h)
   if a!=b:heapq.heappush(h,-(a-b))
  return -h[0] if h else 0

class Solution:
 def removeDuplicates(self,s):
  out=[]
  for c in s:
   if out and out[-1]==c:out.pop()
   else:out.append(c)
  return ''.join(out)

class Solution:
 def heightChecker(self,heights):
  ordered=sorted(heights);return sum(a!=b for a,b in zip(heights,ordered))

from math import gcd
class Solution:
 def gcdOfStrings(self,str1,str2):
  if str1+str2!=str2+str1:return ''
  return str1[:gcd(len(str1),len(str2))]

class Solution:
 def duplicateZeros(self,arr):
  out=[]
  for x in arr:
   out.append(x)
   if x==0:out.append(0)
  arr[:]=out[:len(arr)]
